def _which(step, shops):
    if step < 72 or not shops:
        return "open"
    first = str(shops[0])
    if step < 144 or len(shops) < 2:
        return W_FIRST.get(first, "open")
    key = "%s__%s" % (shops[0], shops[1])
    return W_KEYS.get(key) or W_SIB.get(first, "open")

LEAD_K = 6
LEAD_START = 144
LEAD_SKIP = ("WHEAT", "FERTILIZER")
_lead_used = set()

def _advance_sells(observation, action, tape_name, tape, step):
    """Pull the tape's upcoming SELL orders (next LEAD_K steps, same tape) forward
    to now when the shed already holds the goods. Tape orders first, cap 10."""
    global _lead_used
    if step <= 1:
        _lead_used = set()
    market = list(action.get("market") or [])
    for i, o in enumerate(list(market)):
        if (tape_name, step, i) in _lead_used:
            market.remove(o)
    action["market"] = market
    if step < LEAD_START:
        return action
    shed = dict(_get(_get(observation, "private", {}) or {}, "shed", {}) or {})
    for o in market:
        if o and o[0] == "SELL" and len(o) > 2:
            shed[o[1]] = (shed.get(o[1], 0) or 0) - int(o[2])
    for s in range(step + 1, min(step + LEAD_K, len(tape) - 1) + 1):
        fut = (tape[s] or {}).get("market") or []
        for i, o in enumerate(fut):
            if len(market) >= 10:
                return action
            if not o or o[0] != "SELL" or len(o) < 3 or o[1] in LEAD_SKIP:
                continue
            if (tape_name, s, i) in _lead_used:
                continue
            q = int(o[2])
            if (shed.get(o[1], 0) or 0) >= q:
                market.append(list(o)); shed[o[1]] -= q
                _lead_used.add((tape_name, s, i))
    action["market"] = market
    return action

SEED_TRIM_START = 144
_SUFFIX = {}

def _plant_suffix(tape_name, tape):
    """suffix[i][crop] = PLANT actions for crop in tape[i:]. Built once per tape."""
    suf = _SUFFIX.get(tape_name)
    if suf is None:
        n = len(tape)
        suf = [None] * (n + 1)
        suf[n] = {}
        for i in range(n - 1, -1, -1):
            cur = suf[i + 1]
            a = tape[i]
            add = None
            if isinstance(a, dict):
                units = [a.get("farmer")]
                units.extend(a.get("hands") or [])
                for u in units:
                    if u and len(u) > 1 and u[0] == "PLANT":
                        if add is None:
                            add = dict(cur)
                        add[u[1]] = add.get(u[1], 0) + 1
            suf[i] = cur if add is None else add
        _SUFFIX[tape_name] = suf
    return suf

def _trim_seed_buys(observation, action, tape_name, tape, step):
    """Never buy more seed than the rest of the tape still plants.

    Seed held at turn 720 scores nothing - only bank does - and seed cannot be
    sold back, so a BUY_SEED beyond the tape's remaining plantings is cash
    burned outright. 36 of the 65 tapes do it, $390 a season on average and
    $1,110 at worst, almost all of it one STRAWBERRY order at step 264.

    The cap cannot starve a planting. Buying (remaining - held) leaves exactly
    one seed for every PLANT left in the tape, so the engine's all-or-nothing
    drop (it rejects EVERY PLANT of a crop on a turn that asks for more than is
    held) can never fire because of the trim. `remaining` counts this step too,
    which over-buys by at most one turn's plantings rather than risking that.

    Only from SEED_TRIM_START, where _which has settled on the key tape and
    never switches again - before 144 the suffix belongs to a tape we may not
    end up playing. Measured: every trimmable order in all 65 tapes lands at
    step 264, 624 or 669, so the whole leak is inside that window anyway.
    """
    if step < SEED_TRIM_START:
        return action
    market = action.get("market") or []
    if not any(o and o[0] == "BUY_SEED" for o in market):
        return action
    try:
        suf = _plant_suffix(tape_name, tape)
        remaining = suf[min(step, len(suf) - 1)]
        held = dict(_get(_get(observation, "private", {}) or {}, "seeds", {}) or {})
        out = []
        for o in market:
            if o and o[0] == "BUY_SEED" and len(o) > 2:
                crop = o[1]
                need = remaining.get(crop, 0) - int(held.get(crop, 0) or 0)
                q = min(int(o[2]), need)
                if q <= 0:
                    continue
                o = [o[0], crop, q]
            out.append(o)
        action["market"] = out
    except Exception:
        pass  # degrade to the untrimmed tape order, never to a PASSed turn
    return action

def agent(observation, configuration=None):
    del configuration
    try:
        step = int(_get(observation, "day", 0) or 0) * 24 + int(_get(observation, "hour", 0) or 0)
        step = min(max(step, 0), 718)
        shops = list(_get(_get(observation, "town", {}) or {}, "unlocked_shops", []) or [])
        tape_name = _which(step, shops); tape = _TAPES[tape_name]
        action = copy.deepcopy(tape[min(step, len(tape) - 1)] or {})
        farms = list(_get(observation, "farms", []) or []); p = int(_get(observation, "player", 0) or 0)
        expected = len(_get(farms[p], "hands", []) or []) if p < len(farms) else 0
        hands = list(action.get("hands") or [])
        hands.extend([["PASS"] for _ in range(max(0, expected - len(hands)))])
        action["hands"] = hands[:expected]
        action.setdefault("farmer", ["PASS"]); action.setdefault("market", [])
        action = _trim_seed_buys(observation, action, tape_name, tape, step)
        return _advance_sells(observation, action, tape_name, tape, step)
    except Exception:
        return _pass(observation)
